#include <iostream>
#include <string>
#include <vector>
#include <cstring>
#include <cstdint>
#include <algorithm>
#include <sstream>
#include <fstream>
#include <memory>

namespace auth {

// Token format: [4-byte version][4-byte payload_len][payload][4-byte checksum]
// Payload format: [1-byte role][username_bytes]

struct TokenData {
    uint32_t version;
    uint8_t role;  // 0=guest, 1=user, 2=admin
    std::string username;
    uint32_t checksum;
    bool valid;
};

class TokenValidator {
private:
    static const uint32_t EXPECTED_VERSION = 0x01;
    static const int MAX_USERNAME_LEN = 64;
    static const int MIN_TOKEN_SIZE = 13; // 4+4+1+4 minimum

    static uint32_t computeChecksum(const uint8_t* data, size_t len) {
        uint32_t sum = 0x5A5A5A5A;
        for (size_t i = 0; i < len; i++) {
            sum = ((sum << 3) | (sum >> 29)) ^ data[i];
        }
        return sum;
    }

    static uint32_t readU32(const uint8_t* buf) {
        return (uint32_t)buf[0] | ((uint32_t)buf[1] << 8) |
               ((uint32_t)buf[2] << 16) | ((uint32_t)buf[3] << 24);
    }

public:
    static TokenData parseToken(const std::vector<uint8_t>& token) {
        TokenData result{};
        result.valid = false;

        // Check minimum size
        if (token.size() < MIN_TOKEN_SIZE) {
            return result;
        }

        // Read version
        result.version = readU32(token.data());
        if (result.version != EXPECTED_VERSION) {
            return result;
        }

        // Read payload length
        int payload_len = static_cast<int>(readU32(token.data() + 4));

        // Validate payload length - ensure it fits within the token
        // Token structure: [version:4][payload_len:4][payload:payload_len][checksum:4]
        if (payload_len < 1 || payload_len > MAX_USERNAME_LEN + 1) {
            return result;
        }

        // Verify total token size matches expected
        int expected_size = 4 + 4 + payload_len + 4;
        if (token.size() != static_cast<size_t>(expected_size)) {
            return result;
        }

        // Verify checksum over version + payload_len + payload
        int checksum_offset = 8 + payload_len;
        uint32_t stored_checksum = readU32(token.data() + checksum_offset);
        uint32_t computed_checksum = computeChecksum(token.data(), checksum_offset);
        if (stored_checksum != computed_checksum) {
            return result;
        }

        // Parse payload
        result.role = token[8];
        if (result.role > 2) {
            return result;
        }

        // Extract username from payload
        int username_len = payload_len - 1;
        result.username = std::string(token.begin() + 9, token.begin() + 9 + username_len);

        // Validate username characters
        for (char c : result.username) {
            if (!std::isalnum(static_cast<unsigned char>(c)) && c != '_' && c != '.') {
                return result;
            }
        }

        result.valid = true;
        result.checksum = stored_checksum;
        return result;
    }
};

class AccessController {
private:
    struct Permission {
        std::string resource;
        uint8_t min_role;
    };

    std::vector<Permission> permissions_;

public:
    AccessController() {
        permissions_ = {
            {"public", 0},
            {"documents", 1},
            {"settings", 1},
            {"admin_panel", 2},
            {"user_management", 2},
            {"system_config", 2}
        };
    }

    bool checkAccess(const TokenData& token, const std::string& resource) {
        if (!token.valid) return false;

        for (const auto& perm : permissions_) {
            if (perm.resource == resource) {
                return token.role >= perm.min_role;
            }
        }
        return false; // Unknown resource = deny
    }
};

class SessionManager {
private:
    struct Session {
        TokenData token;
        int64_t created_at;
        int64_t last_access;
        int request_count;
    };

    std::vector<Session> sessions_;
    static const int MAX_SESSIONS = 100;
    static const int MAX_REQUESTS_PER_SESSION = 1000;
    static const int64_t SESSION_TIMEOUT = 3600; // 1 hour

    int64_t currentTime() {
        return static_cast<int64_t>(std::time(nullptr));
    }

public:
    // Rate limiting check
    bool isRateLimited(const std::string& username) {
        auto now = currentTime();
        for (auto& session : sessions_) {
            if (session.token.username == username) {
                if (now - session.last_access > SESSION_TIMEOUT) {
                    continue; // expired session
                }
                if (session.request_count >= MAX_REQUESTS_PER_SESSION) {
                    return true;
                }
                session.request_count++;
                session.last_access = now;
                return false;
            }
        }
        return false;
    }

    bool createSession(const TokenData& token) {
        if (!token.valid) return false;

        // Cleanup expired sessions
        auto now = currentTime();
        sessions_.erase(
            std::remove_if(sessions_.begin(), sessions_.end(),
                [now, this](const Session& s) {
                    return now - s.last_access > SESSION_TIMEOUT;
                }),
            sessions_.end()
        );

        if (sessions_.size() >= MAX_SESSIONS) {
            return false;
        }

        sessions_.push_back({token, now, now, 0});
        return true;
    }
};

} // namespace auth

class RequestHandler {
private:
    auth::AccessController acl_;
    auth::SessionManager sessions_;
    std::ofstream audit_log_;

    void logAccess(const std::string& user, const std::string& resource, bool granted) {
        if (audit_log_.is_open()) {
            audit_log_ << currentTimestamp() << "|" << user << "|" 
                      << resource << "|" << (granted ? "GRANTED" : "DENIED") << "\n";
            audit_log_.flush();
        }
    }

    std::string currentTimestamp() {
        auto t = std::time(nullptr);
        char buf[32];
        std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", std::gmtime(&t));
        return std::string(buf);
    }

public:
    RequestHandler() {
        audit_log_.open("/var/log/app/access.log", std::ios::app);
    }

    std::string handleRequest(const std::vector<uint8_t>& raw_token, 
                              const std::string& resource) {
        // Parse and validate token
        auto token = auth::TokenValidator::parseToken(raw_token);
        if (!token.valid) {
            return "ERROR: Invalid token";
        }

        // Rate limiting
        if (sessions_.isRateLimited(token.username)) {
            return "ERROR: Rate limited";
        }

        // Create/update session
        sessions_.createSession(token);

        // Check access
        bool granted = acl_.checkAccess(token, resource);
        logAccess(token.username, resource, granted);

        if (granted) {
            return "ACCESS GRANTED to " + resource + " for " + token.username;
        }
        return "ACCESS DENIED";
    }
};

// Helper to create tokens for testing
std::vector<uint8_t> createToken(uint8_t role, const std::string& username) {
    std::vector<uint8_t> token;

    // Version
    uint32_t version = 0x01;
    token.push_back(version & 0xFF);
    token.push_back((version >> 8) & 0xFF);
    token.push_back((version >> 16) & 0xFF);
    token.push_back((version >> 24) & 0xFF);

    // Payload length
    uint32_t payload_len = 1 + username.size();
    token.push_back(payload_len & 0xFF);
    token.push_back((payload_len >> 8) & 0xFF);
    token.push_back((payload_len >> 16) & 0xFF);
    token.push_back((payload_len >> 24) & 0xFF);

    // Payload: role + username
    token.push_back(role);
    for (char c : username) {
        token.push_back(static_cast<uint8_t>(c));
    }

    // Compute checksum
    uint32_t sum = 0x5A5A5A5A;
    for (size_t i = 0; i < token.size(); i++) {
        sum = ((sum << 3) | (sum >> 29)) ^ token[i];
    }
    token.push_back(sum & 0xFF);
    token.push_back((sum >> 8) & 0xFF);
    token.push_back((sum >> 16) & 0xFF);
    token.push_back((sum >> 24) & 0xFF);

    return token;
}

int main(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <role:0-2> <resource>" << std::endl;
        return 1;
    }

    int role = std::atoi(argv[1]);
    std::string resource = argv[2];

    // Get username from environment
    const char* user_env = std::getenv("APP_USER");
    std::string username = user_env ? user_env : "anonymous";

    // Validate resource name
    for (char c : resource) {
        if (!std::isalnum(static_cast<unsigned char>(c)) && c != '_') {
            std::cerr << "Invalid resource name" << std::endl;
            return 1;
        }
    }

    auto token = createToken(static_cast<uint8_t>(role), username);

    RequestHandler handler;
    std::cout << handler.handleRequest(token, resource) << std::endl;

    return 0;
}
